import os

TEXT_EXTS = {'.csv', '.tsv', '.json', '.md', '.txt', '.dat', '.log', '.yml', '.yaml', '.py', '.html'}

def main():
    for root, dirs, files in os.walk('.'):
        dirs[:] = [d for d in dirs if not d.startswith('.')]
        depth = root.count(os.sep)
        indent = '  ' * depth
        print(f"{indent}{root}/")
        for f in sorted(files):
            fpath = os.path.join(root, f)
            size = os.path.getsize(fpath)
            ext = os.path.splitext(f)[1].lower()
            print(f"{indent}  {f}  ({size} bytes)")
            if ext in TEXT_EXTS:
                print(f"{indent}    --- contents start ---")
                try:
                    with open(fpath, 'r', encoding='utf-8', errors='replace') as fh:
                        lines = fh.readlines()
                    # Print up to 300 lines per file; note truncation otherwise.
                    shown = lines[:300]
                    for ln in shown:
                        print(f"{indent}    | {ln.rstrip()}")
                    if len(lines) > 300:
                        print(f"{indent}    | ... [truncated: {len(lines) - 300} more lines]")
                except Exception as e:
                    print(f"{indent}    | ERROR reading: {e}")
                print(f"{indent}    --- contents end ---")

if __name__ == '__main__':
    main()

